#include <iostream>
#include <memory>
#include <vector>
using namespace std;

int main() {
    int n = 0;
    cin >> n;
    unique_ptr<vector<int>> p = make_unique<vector<int>>();
    for (int i = 0; i < n; i++) {
        int x = 0;
        cin >> x;
        p->push_back(x);
    }
    unique_ptr<vector<int>> q = move(p);
    cout << q->size() << endl;
    return 0;
}
